import {RULES,actionEnergyCost} from './evolution.js';
import {spendEnergy,ENERGY_DEFICIT_FACTOR} from './energy-budget.js';
import {DT,ACTION_DURATIONS,SUBSTEPS} from './action-timing.js';
import {ACTIONS} from './action-catalog.js';
import {v,p,a,table,details} from './guide-markup.js';

/** Учебные входы заданы явно; последствия считает общая функция физики. */
export function guideDeficitExample({energy=.25,health=10,cost=1}={}){
 const body={energy,health},world={stats:{spent:0,brainSpent:0,actionSpent:0}};
 const paid=spendEnergy(world,body,cost);return {before:{energy,health},cost,paid,missing:cost-paid,after:body,healthLoss:health-body.health};
}
const example=guideDeficitExample();
export const GUIDE_ENERGY_TEXT={
 'guide-energy-body':p('Энергия оплачивает деятельность и вычисления. Если запаса не хватает, неоплаченная часть расхода уменьшает здоровье. Поэтому житель может продолжать жить при нулевой энергии, пока сохраняется здоровье; усвоение пищи способно снова пополнить запас энергии.')
 +table('Ресурсы тела',['Что наблюдать','Как меняется'],[
 ['Энергия',`У основателя начинается с ${v(RULES.initialEnergy)}, у ребёнка — с ${v(RULES.newbornEnergy)}. Пополняется усвоением, тратится на деятельность, основной мозг и рождение ребёнка.`],
 ['Здоровье','Начинается полным. Уменьшается при неоплаченном расходе энергии; еда его не восстанавливает. При исчерпании житель погибает.'],
 ['Инвентарь',`Запас до ${v(RULES.inventoryCapacity,'порций')}. Сбор добавляет порцию; еда и выкладывание забирают её.`],
 ['Желудок',`Вмещает ${v(RULES.stomachCapacity,'энергии')} пищи. Еда добавляет ${v(RULES.foodEnergy)}; усвоение постепенно освобождает место.`],
 ])
 +p(`Пример: перед расходом у жителя ${v(example.before.energy,'энергии')} и ${v(example.before.health,'здоровья')}, требуется ${v(example.cost,'энергии')}. Из запаса оплачивается ${v(example.paid)}, дефицит составляет ${v(example.missing)}. После оплаты остаётся ${v(example.after.energy,'энергии')} и ${v(example.after.health,'здоровья')}: потеря здоровья — ${v(example.healthLoss)}.`)
 +details('Точные правила расходов и усвоения',
 p(`Каждая недостающая единица энергии уменьшает здоровье примерно на ${v(ENERGY_DEFICIT_FACTOR)}. Функция ограничивает оба запаса снизу нулём. Если энергия ровно покрывает расход, здоровье не уменьшается. Отдельного штрафа только за нахождение на нуле нет.`)
 +table('Обычная деятельность: полная ставка без мышления',['Действие','Энергия за 1 Т','За завершённый процесс'],[0,6,7,8,10].map(id=>[ACTIONS[id],v(actionEnergyCost(id)),v(actionEnergyCost(id)*ACTION_DURATIONS[id]/SUBSTEPS)]))
 +p(`Обычный процесс оплачивается на каждом подшаге: его ставка за Т умножается на ${v(DT,'Т')}. При отмене оплаченная часть остаётся расходом. Роды устроены отдельно: сумма списывается при завершении, без этой обычной подшаговой ставки; подробнее — ${a('selection','рождение потомка')}.`)
 +p(`Перед оплатой текущей деятельности происходит усвоение из желудка. Его скорость равна энергии порции, делённой на выбранное время усвоения. Сейчас контекст пособия задаёт <span class="guide-value" data-guide-param="digestionTime">${v(RULES.foodEnergy/RULES.digestionRate,'Т').replace(/<[^>]+>/g,'')}</span> на порцию. Фактически усваивается не больше оставшегося содержимого желудка. Энергия, которая не помещается в заполненный запас тела, теряется, а желудок всё равно освобождается.`)
 +p(`Основной мозг оплачивается в момент принятия решения. Цена зависит от условных вычислительных операций схемы и выполненного обучения; это не измеренное время процессора. Нулевая обучаемость или выключенное обучение не делают сам выбор бесплатным. Изменение числа Workers не меняет физическую цену. Подробнее — ${a('brain','устройство и цена мозга')}.`)
 +p('В статистике энергетический расход содержит фактически списанную энергию. Если часть цены оплачена здоровьем, эта часть не записывается как энергия, которой у жителя не было. Поэтому ряд энергетических затрат сам по себе не показывает всю потерю здоровья от дефицита.'))
 +details('Когда заканчивается жизнь',
 p(`Во время обновления тела сначала идут усвоение и расход деятельности, затем проверка гибели — до завершения процесса. Житель погибает при исчерпании здоровья или достижении предельного возраста ${v(RULES.maxAge,'Т')}. Если одновременно исчерпано здоровье, причина записывается как истощение; иначе — предел возраста.`)
 +p('Оплата решения тоже может исчерпать здоровье. Тогда выбранное действие не начинается, а текущий процесс прекращается. Текущая временная модель не наносит случайных повреждений от рельефа: вода запрещает движение, а не уменьшает здоровье.')
 +p(`После гибели житель исключается из расчёта, а его завершённая жизнь попадает в историю. Оставшиеся инвентарь, энергия тела и содержимое желудка списываются как потери; труп не создаёт источник или запас пищи на карте. Ранее ${a('deposits','выложенная пища')} остаётся на клетке независимо от жизни владельца.`))
 +p(`Связанные темы: ${a('time','порядок событий')}, ${a('actions','действия и прерывания')}, ${a('food','питание')}, ${a('research','показатели жизни и населения')}.`),
};
